    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* ── Main Message Area ── */
.chat-main {
    flex: 0 0 55%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-right: 1px solid #2c2d30;
    transition: flex-basis 0.25s ease;
}

.chat-main.full-width {
