+        _messages.Add(msg);
+        _messageSkip++;
+        _newMessageText = "";
+    }
+
+    private async Task OnMessageKeyDownAsync(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+        {
+            await SendMessageAsync();
+        }
+    }
+
+    // ── Thread ──
+
+    private async Task OpenThreadAsync(Message rootMessage)
+    {
+        _threadRootMessage = rootMessage;
+        _threadReplyText = "";
+        _emojiPickerMessageId = null;
+
+        var allReplies = await ChatService.GetThreadAsync(rootMessage.Id);
+        // Exclude the root message itself from the reply list
+        _threadMessages = allReplies.Where(m => m.Id != rootMessage.Id).ToList();
+        _threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        _threadOpen = false;
+        _threadRootMessage = null;
+        _threadMessages = null;
+        _threadReplyText = "";
+    }
+
+    private async Task SendThreadReplyAsync()
+    {
+        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null) return;
+
+        var reply = await ChatService.SendMessageAsync(
+            _threadRootMessage.ChannelId, _threadReplyText.Trim(), _threadRootMessage.Id);
+
+        _threadMessages ??= new();
+        _threadMessages.Add(reply);
+        _threadReplyText = "";
+
+        // Update thread summary count
+        if (_threadSummaries.TryGetValue(_threadRootMessage.Id, out var existing))
+        {
+            _threadSummaries[_threadRootMessage.Id] = existing with
+            {
+                ReplyCount = existing.ReplyCount + 1,
+                LastReplyAt = reply.SentAt
+            };
+        }
+        else
+        {
+            _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
+                _threadRootMessage.Id, 1, reply.SentAt);
+        }
+    }
+
+    private async Task OnThreadKeyDownAsync(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+        {
+            await SendThreadReplyAsync();
+        }
+    }
+
+    // ── Reactions ──
+
+    private void ToggleEmojiPicker(int messageId)
+    {
+        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
+    }
+
+    private async Task AddReactionAsync(int messageId, string emoji)
+    {
+        _emojiPickerMessageId = null;
+        await ChatService.AddReactionAsync(messageId, emoji);
+
+        // Refresh messages to show updated reactions
+        if (_messages is not null)
+        {
+            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messageSkip);
+            _messages = refreshed;
+        }
+
+        // Also refresh thread if open
+        if (_threadOpen && _threadRootMessage is not null)
+        {
+            var allReplies = await ChatService.GetThreadAsync(_threadRootMessage.Id);
+            _threadMessages = allReplies.Where(m => m.Id != _threadRootMessage.Id).ToList();
+            // Update root message too
+            var updatedRoot = allReplies.FirstOrDefault(m => m.Id == _threadRootMessage.Id);
+            if (updatedRoot is not null) _threadRootMessage = updatedRoot;
+        }
+    }
+
+    // ── Helpers ──
+
+    private void BuildThreadSummaries()
+    {
+        if (_messages is null) return;
+
+        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
+        var grouped = replies.GroupBy(m => m.ReplyToId!.Value);
+
+        foreach (var g in grouped)
+        {
+            _threadSummaries[g.Key] = new ThreadSummary(
+                g.Key, g.Count(), g.Max(m => m.SentAt));
+        }
+    }
+
+    private ThreadSummary? GetThreadSummary(int messageId)
+    {
+        return _threadSummaries.GetValueOrDefault(messageId);
+    }
+
+    private static string FormatRelativeTime(DateTime sentAt)
+    {
+        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
+
+        if (diff.TotalSeconds < 60) return "just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
+        return sentAt.ToString("MMM d, yyyy");
+    }
+
+    private static string TruncateDescription(string description)
+    {
+        return description.Length > 50 ? description[..47] + "…" : description;
+    }
+}
+

